// Complete PDF processing pipeline
async function pdfProcessingPipeline() {
 const pdf = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
 path: 'pdf-wasm',
 name: 'pdf-wasm'
 });

 // Step 1: HTML to PDF conversion
 const htmlContent = `
 <h1>Rapport Technique</h1>
 <h2>Introduction</h2>
 <p>Ce document présente les résultats de notre analyse technique.</p>
 <h2>Métriques de Performance</h2>
 <p>Les performances ont été mesurées sur plusieurs indicateurs clés.</p>
 `;

 console.log(' Converting HTML to PDF...');
 let result = pdf.call('htmlToPDF', htmlContent);
