 let pdfData = result.pdfData;
 console.log(' HTML converted:', result.size, 'bytes');

 // Step 2: Add performance data table
 const performanceTable = {
 headers: ['Métrique', 'Valeur Actuelle', 'Objectif', 'Status'],
 rows: [
 ['Temps de Réponse', '150ms', '200ms', ' OK'],
 ['Disponibilité', '99.9%', '99.5%', ' Dépassé'],
 ['Throughput', '1200 rps', '1000 rps', ' Dépassé'],
 ['Erreurs', '0.1%', '0.5%', ' OK']
 ]
 };

 console.log(' Adding performance table...');
 result = pdf.call('addTable', pdfData, JSON.stringify(performanceTable));
 if (result.error) throw new Error(result.error);

 pdfData = result.pdfData;
 console.log(' Table added:', result.columns, 'columns,', result.rows, 'rows');

 // Step 3: Add trend chart
 const trendChart = {
 type: 'bar',
 title: 'Évolution des Performances (6 mois)',
 data: [
 { label: 'Jan', value: 85 },
 { label: 'Fév', value: 88 },
 { label: 'Mar', value: 92 },
 { label: 'Avr', value: 95 },
 { label: 'Mai', value: 97 },
 { label: 'Jun', value: 99 }
 ]
 };

 console.log(' Adding trend chart...');
 result = pdf.call('addChart', pdfData, JSON.stringify(trendChart));
 if (result.error) throw new Error(result.error);

 pdfData = result.pdfData;
 console.log(' Chart added:', result.dataPoints, 'data points');

 // Step 4: Comprehensive analysis
 console.log(' Analyzing final document...');
 const analysis = pdf.call('analyzePDF', pdfData);
 if (analysis.error) throw new Error(analysis.error);

 console.log(' Analysis results:');
 console.log('- File size:', analysis.fileSize, 'bytes');
 console.log('- Pages:', analysis.pages);
 console.log('- Fonts used:', analysis.fonts.join(', '));
 console.log('- Optimization tips:', analysis.optimizationTips.length);

 // Step 5: Intelligent optimization
 console.log(' Optimizing document...');
 result = pdf.call('optimizePDF', pdfData, 'balanced');
 if (result.error) throw new Error(result.error);

 console.log(' Optimization complete:');
 console.log('- Original size:', result.originalSize, 'bytes');
 console.log('- Optimized size:', result.optimizedSize, 'bytes');
 console.log('- Space saved:', result.savingsPercent + '%');
 console.log('- Optimizations:', result.optimizations.join(', '));

 // Final download
 const blob = new Blob([atob(result.pdfData)], {type: 'application/pdf'});
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = 'technical-report-optimized.pdf';
 a.click();

 return {
 originalSize: result.originalSize,
 optimizedSize: result.optimizedSize,
 savings: result.savingsPercent,
 analysis: analysis
 };
}

